class Solution {
public:
vector<int> postorderTraversal(TreeNode* root) {
    vector<int> result;
    if (!root) return result;
    stack<TreeNode*> s;
    TreeNode* last = nullptr;
    while (!s.empty() || root) {
        if (root) {
            s.push(root);
            root = root->left;
        } else {
            TreeNode* node = s.top();
            if (node->right && last != node->right)
                root = node->right;
            else {
                result.push_back(node->val);
                last = node;
                s.pop();
            }
        }
    }
    return result;
}
};
